/* TF.EX's Notification (vendor/tfex/src/network/TF.EX.Domain/CustomComponent/Notification.cs): a real Monocle.Entity subclass on the
 * Switch, generated by tools/tfex/translator (tfex/gen/tfexgen_Notification.*). This API is what our call sites use (Notification.cpp:
 * texts as ASCII, rollback-safe between ticks, behind hw.txt "notif 1"). */
#pragma once
#include <cstdint>

namespace tfex::Notification {

/* public static Notification Create(Scene scene, string text, int appearDuration = 20, int stayingDuration = 250, bool isSticky = false,
 * bool withoutAnimation = false). text: ASCII (made a managed string here). Returns the game object, or null. */
void* Create(void* scene, const char* text, int appearDuration = 20, int stayingDuration = 250, bool isSticky = false, bool withoutAnimation = false);
void CreateOrDefer(void* scene, const char* text);
void FlushDeferred(void* scene);
void ClearDeferred();
void Clear(void* scene, int layerIndex);

/* Off by default (hw.txt "notif 1" turns it on) until the runtime-made class is checked on the console:
 * while off, EnsureClass fails and Create/CreateOrDefer/... do nothing. */
void SetEnabled(bool on);
bool Enabled();
/* The class (runtime type, descriptor, vtable, statics) is made on first use; call this where no rollback window is open (a menu). */
bool EnsureClass();
void* RuntimeType();   /* the (generated) class's runtime type, for `is` tests; null before EnsureClass */
/* TFEX-DIFF: S-rollback. A Canvas shared per size (made in the menu): the generated ctor's `new Canvas(w, h)` through the translator's ledger */
void* SharedCanvas(int32_t width, int32_t height);

} // namespace tfex::Notification
